server_tools = {"search_kb": {"risk": "read"}, "create_ticket": {"risk": "external_write"}}

def call_mcp_tool(user, name, args):
    if name not in server_tools:
        raise ValueError("unknown tool")
    validate_args(name, args)
    risk = server_tools[name]["risk"]
    if risk == "external_write" and not user.get("approved"):
        return {"status": "needs_approval", "tool": name, "args": args}
    result = {"content": f"result from {name}", "provenance": "mcp_server"}
    return result

print(call_mcp_tool({"id": "u1", "approved": False}, "create_ticket", {"title": "Bug"}))
